import com.fabio.aether.Rules;
public class RulesTest {static int n;static void check(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS "+s);n++;}public static void main(String[] args){check(Rules.tile(20,20)==0,"spawn livre");check(Rules.tile(0,9)==3,"borda solida");check(Rules.tile(39,10)==3,"outra borda solida");check(!Rules.solid(0),"grama transitavel");check(Rules.solid(2),"rocha bloqueia");check(Rules.damage(2)>Rules.damage(1),"dano progride");check(Rules.clamp(-2,0,100)==0,"vida nao negativa");check(Rules.clamp(120,0,100)==100,"cura limitada");check(Rules.xpNeed(2)>Rules.xpNeed(1),"XP cresce");for(int x=0;x<40;x++)for(int y=0;y<40;y++)checkTile(x,y);check(true,"1600 tiles validos e deterministic os");System.out.println(n+" testes aprovados");}static void checkTile(int x,int y){int t=Rules.tile(x,y);if(t<0||t>3||t!=Rules.tile(x,y))throw new AssertionError("tile invalido");}}
